#!/usr/bin/env bash
# Reproduce S5 lumpi-track submission 's5' (model-lumpi-track/routed-g5): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-lumpi-track/routed-g5/submissions/2026-10-11_s5/lumpi_s5_submission.zip (md5 9f2c925c3976679b5b2038bfde5f7566).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-lumpi-track/routed-g5/test/reproduce_s5.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-lumpi-track/routed-g5/test/output/repro_s5
mkdir -p $OUT
# member g1: model-lumpi-track/pointpillars-g1, checkpoint md5 16e68b8b9142688967e4b3d006ac9d54
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1/test/postprocess.yaml --out $OUT/predictions_g1.json
# member g1_tta: model-lumpi-track/pointpillars-g1, checkpoint md5 16e68b8b9142688967e4b3d006ac9d54
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_g1_tta.json
# member g1v3: model-lumpi-track/pointpillars-g1v3, checkpoint md5 e403acdc3ae30a84de3989da34619440
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess.yaml --out $OUT/predictions_g1v3.json
# member g1v3_tta: model-lumpi-track/pointpillars-g1v3, checkpoint md5 e403acdc3ae30a84de3989da34619440
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_g1v3_tta.json
# member ppros_tta: model-lumpi-track/pointpillars-ros-g1v3, checkpoint md5 590e9f16fe22d1f429d4827392c1f0ba
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-ros-g1v3 --ckpt model-lumpi-track/pointpillars-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_ppros_tta.json
# member pv_tta: model-lumpi-track/pvrcnnpp-g1v3, checkpoint md5 fd25c22b76cf55863ca66a9ce28bc508
python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-g1v3 --ckpt model-lumpi-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pv_tta.json
# member pvros_tta: model-lumpi-track/pvrcnnpp-ros-g1v3, checkpoint md5 66c1f05a2e602113dd011d96a22ec334
python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-ros-g1v3 --ckpt model-lumpi-track/pvrcnnpp-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pvrcnnpp-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros_tta.json
# member vrgb_tta: model-lumpi-track/voxelrcnn-gblobs-g1v3, checkpoint md5 c9dc86caa2ca833837162ed0c3242d50
python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-gblobs-g1v3 --ckpt model-lumpi-track/voxelrcnn-gblobs-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/voxelrcnn-gblobs-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrgb_tta.json
# member vrros_tta: model-lumpi-track/voxelrcnn-ros-g1v3, checkpoint md5 5415c1ceb113d8ca31fcac3ed2ba4a57
python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-ros-g1v3 --ckpt model-lumpi-track/voxelrcnn-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/voxelrcnn-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros_tta.json
python common/tools/route_predictions.py merge model-lumpi-track/routed-g5 --pred g1=$OUT/predictions_g1.json --pred g1_tta=$OUT/predictions_g1_tta.json --pred g1v3=$OUT/predictions_g1v3.json --pred g1v3_tta=$OUT/predictions_g1v3_tta.json --pred ppros_tta=$OUT/predictions_ppros_tta.json --pred pv_tta=$OUT/predictions_pv_tta.json --pred pvros_tta=$OUT/predictions_pvros_tta.json --pred vrgb_tta=$OUT/predictions_vrgb_tta.json --pred vrros_tta=$OUT/predictions_vrros_tta.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-lumpi-track/routed-g5 --tag s5 --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/lumpi-track/pcdet/g1-v2/points" ]; then SYN=(--syn-split val --syn-list model-lumpi-track/routed-g5/submissions/2026-10-11_s5/synthetic_ids.txt); else SYN=(--syn-zip model-lumpi-track/routed-g5/submissions/2026-10-11_s5/lumpi_s5_submission.zip --syn-list model-lumpi-track/routed-g5/submissions/2026-10-11_s5/synthetic_ids.txt); fi
python common/tools/package_submission.py model-lumpi-track/routed-g5 --tag repro-s5 --pred $OUT/predictions.json --synthetic pcdet/g1-v2 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of s5' --reproduction
Z=model-lumpi-track/routed-g5/test/output/repro-s5/submission.zip
python common/tools/check_submission.py --track lumpi $Z --official
python common/tools/reproduce_submission.py model-lumpi-track/routed-g5 --tag s5 --compare-zip $Z     # predictions and frames against the scored zip
